package fr.heetstudio.confee.format;

/**
 * Marks the comments Confee writes in its own files (spec 5.3): {@code #:} / {@code //:} instead of {@code #} /
 * {@code //}. A comment line without the marker was written by hand and is never touched.
 * <p>Internal: may change without notice.</p>
 */
public final class CommentMarker {

    /** Written right after the comment prefix of a format ({@code #} or {@code //}). */
    public static final String MARK = ":";

    private CommentMarker() {
    }

    /** One line of a comment generated by Confee ({@code @Comment}, range / allowed values hint). */
    public static String generated(String prefix, String line) {
        return line.isEmpty() ? prefix + MARK : prefix + MARK + " " + line;
    }

    /**
     * One line of a comment read from the previous file and written again as is (unknown keys): a generated line keeps
     * its marker, any other line stays without one.
     *
     * @param line comment text as returned by the parsers (prefix and first space removed)
     */
    public static String carried(String prefix, String line) {
        if (line.isEmpty()) {
            return prefix;
        }
        return line.startsWith(MARK) ? prefix + line : prefix + " " + line;
    }

    /** Whether a line of a file, leading spaces removed, is a comment line generated by Confee. */
    public static boolean isGenerated(String strippedLine, String prefix) {
        return strippedLine.startsWith(prefix + MARK);
    }
}
